package com.sakhtemanyar;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.json.*;

public class MainActivity extends Activity {
    static final String API="https://okizneyesdwiundvadpe.supabase.co/functions/v1/api";
    LinearLayout root, content, drawer; FrameLayout shell; TextView title; String session="", role=""; ArrayList<String> pages=new ArrayList<>();
    int navy=Color.rgb(15,31,48), teal=Color.rgb(18,130,130), bg=Color.rgb(246,248,251), white=Color.WHITE;
    GradientDrawable gd(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}
    TextView tv(String s,float z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(navy);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setPadding(24,14,24,14);return t;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setTextColor(white);b.setBackground(gd(teal,28));b.setAllCaps(false);b.setPadding(18,8,18,8);return b;}
    EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(15);e.setGravity(Gravity.RIGHT);e.setPadding(22,4,22,4);e.setBackground(gd(white,22));return e;}
    @Override public void onCreate(Bundle b){super.onCreate(b);showLogin();}
    void base(String page){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root); LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(8,8,8,8);bar.setBackgroundColor(navy); TextView menu=tv("☰",28);menu.setTextColor(white);menu.setGravity(Gravity.CENTER);bar.addView(menu,new LinearLayout.LayoutParams(58,58)); title=tv(page,19);title.setTextColor(white);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,58,1)); root.addView(bar);menu.setOnClickListener(v->toggleDrawer()); shell=new FrameLayout(this);root.addView(shell,new LinearLayout.LayoutParams(-1,0,1)); content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(20,20,20,20);ScrollView sv=new ScrollView(this);sv.addView(content);shell.addView(sv,new FrameLayout.LayoutParams(-1,-1)); drawer=new LinearLayout(this);drawer.setOrientation(LinearLayout.VERTICAL);drawer.setGravity(Gravity.TOP);drawer.setPadding(16,24,16,16);drawer.setBackgroundColor(white);FrameLayout.LayoutParams dp=new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.78),-1,Gravity.RIGHT);dp.setMargins(0,0,0,0);shell.addView(drawer,dp);drawer.setVisibility(View.GONE);}
    void toggleDrawer(){drawer.setVisibility(drawer.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);}
    void nav(String name, final Runnable r){Button b=btn(name);b.setTextColor(navy);b.setBackground(gd(Color.rgb(239,244,247),24));b.setOnClickListener(v->{drawer.setVisibility(View.GONE);r.run();});drawer.addView(b,new LinearLayout.LayoutParams(-1,58));Space sp=new Space(this);drawer.addView(sp,new LinearLayout.LayoutParams(1,8));}
    void managerDrawer(){drawer.removeAllViews();TextView h=tv("مدیریت ساختمان",20);h.setTextColor(teal);h.setTypeface(null,1);drawer.addView(h);nav("داشبورد",()->managerHome());nav("واحدها و ساکنان",()->units());nav("شارژها و هزینه‌ها",()->charges());nav("تعمیرات",()->repairs());nav("پرداخت‌ها",()->payments());nav("اشتراک سامانه",()->plans());nav("خروج",()->showLogin());}
    void residentDrawer(){drawer.removeAllViews();TextView h=tv("پنل ساکن",20);h.setTextColor(teal);h.setTypeface(null,1);drawer.addView(h);nav("داشبورد من",()->residentHome());nav("پرداخت بدهی",()->residentPay());nav("خروج",()->showLogin());}
    void adminDrawer(){drawer.removeAllViews();TextView h=tv("مدیرکل سامانه",20);h.setTextColor(teal);h.setTypeface(null,1);drawer.addView(h);nav("داشبورد سامانه",()->adminHome());nav("ساختمان‌ها",()->adminBuildings());nav("اشتراک‌ها",()->adminPlans());nav("تنظیمات سامانه",()->adminSettings());nav("خروج",()->showLogin());}
    void card(String head,String val){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(8,8,8,8);c.setBackground(gd(white,28));TextView a=tv(head,14);a.setTextColor(Color.DKGRAY);TextView v=tv(val,21);v.setTextColor(teal);v.setTypeface(null,1);c.addView(a);c.addView(v);content.addView(c,new LinearLayout.LayoutParams(-1,100));Space s=new Space(this);content.addView(s,new LinearLayout.LayoutParams(1,12));}
    void showLogin(){base("ساختمان‌یار");title.setText("ورود به سامانه");content.setGravity(Gravity.CENTER_HORIZONTAL);TextView logo=tv("ساختمان‌یار",30);logo.setTextColor(teal);logo.setTypeface(null,1);content.addView(logo,new LinearLayout.LayoutParams(-1,100));TextView sub=tv("مدیریت هوشمند ساختمان",16);content.addView(sub);EditText u=input("نام کاربری");EditText p=input("رمز عبور");p.setInputType(129);content.addView(u,new LinearLayout.LayoutParams(-1,60));content.addView(p,new LinearLayout.LayoutParams(-1,60));Space s=new Space(this);content.addView(s,new LinearLayout.LayoutParams(1,16));Button m=btn("ورود مدیر ساختمان");Button r=btn("ورود ساکن");Button a=btn("ورود مدیرکل سامانه");Button reg=btn("ثبت مدیر اولیه");content.addView(m,new LinearLayout.LayoutParams(-1,58));content.addView(r,new LinearLayout.LayoutParams(-1,58));content.addView(a,new LinearLayout.LayoutParams(-1,58));content.addView(reg,new LinearLayout.LayoutParams(-1,58));m.setOnClickListener(v->login(u.getText().toString(),p.getText().toString(),"manager"));r.setOnClickListener(v->login(u.getText().toString(),p.getText().toString(),"resident"));a.setOnClickListener(v->login(u.getText().toString(),p.getText().toString(),"admin"));reg.setOnClickListener(v->register());}
    void login(String u,String p,String r){new Thread(()->{try{JSONObject b=new JSONObject().put("action",r.equals("admin")?"admin_login":r.equals("resident")?"login_resident":"login_manager").put("username",u).put("password",p);String x=post(b,null);JSONObject j=new JSONObject(x);if(j.has("error"))throw new Exception(j.getString("error"));session=j.getString("session");role=r;runOnUiThread(()->{if(r.equals("admin")){adminDrawer();adminHome();}else if(r.equals("resident")){residentDrawer();residentHome();}else{managerDrawer();managerHome();}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
    String post(JSONObject b,String tok)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(API).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("Content-Type","application/json");if(tok!=null)c.setRequestProperty("Authorization","Bearer "+tok);c.getOutputStream().write(b.toString().getBytes(StandardCharsets.UTF_8));InputStream is=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();return new String(is.readAllBytes(),StandardCharsets.UTF_8);}
    void register(){base("ثبت مدیر اولیه");EditText n=input("نام ساختمان"),ad=input("آدرس ساختمان"),u=input("نام کاربری مدیر"),p=input("رمز عبور");p.setInputType(129);content.addView(n);content.addView(ad);content.addView(u);content.addView(p);Button b=btn("ثبت ساختمان");content.addView(b);b.setOnClickListener(v->new Thread(()->{try{JSONObject j=new JSONObject().put("action","register_manager").put("building_name",n.getText()).put("address",ad.getText()).put("username",u.getText()).put("password",p.getText());String x=post(j,null);JSONObject z=new JSONObject(x);if(z.has("error"))throw new Exception(z.getString("error"));session=z.getString("session");role="manager";runOnUiThread(()->{managerDrawer();managerHome();});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start());}
    void managerHome(){base("داشبورد مدیر ساختمان");managerDrawer();card("وضعیت سامانه","مدیریت ساختمان فعال");card("واحدها","از منوی کشویی مدیریت کنید");card("مالی","شارژ، تعمیرات و پرداخت‌ها");card("اشتراک","وضعیت و تمدید اشتراک");}
    void units(){base("واحدها و ساکنان");managerDrawer();Button add=btn("＋ افزودن واحد");content.addView(add);add.setOnClickListener(v->addUnit());call("dashboard",j->{JSONArray a=j.optJSONArray("units");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card("واحد "+x.optString("unit_no"),"تعداد ساکن: "+x.optInt("resident_count"));}});}
    void addUnit(){EditText n=input("شماره واحد"),r=input("تعداد ساکن"),o=input("نام مالک/ساکن");content.addView(n);content.addView(r);content.addView(o);Button b=btn("ذخیره");content.addView(b);b.setOnClickListener(v->callObj(new JSONObject().put("action","add_unit").put("unit_no",n.getText()).put("residents_count",r.getText()).put("resident_name",o.getText()),j->{toast("واحد ثبت شد");units();}));}
    void charges(){base("شارژ و هزینه‌ها");managerDrawer();Button b=btn("＋ ثبت هزینه جدید");content.addView(b);b.setOnClickListener(v->addCharge());call("dashboard",j->{JSONArray a=j.optJSONArray("charges");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card(x.optString("title"),money(x.optDouble("amount_rial")));}});}
    void addCharge(){EditText t=input("عنوان هزینه"),a=input("مبلغ به تومان");content.addView(t);content.addView(a);Button b=btn("ثبت هزینه");content.addView(b);b.setOnClickListener(v->callObj(new JSONObject().put("action","add_charge").put("title",t.getText()).put("amount_rial",Long.parseLong(a.getText().toString())*10),j->{toast("هزینه ثبت شد");charges();}));}
    void repairs(){base("تعمیرات");managerDrawer();Button b=btn("＋ ثبت تعمیرات");content.addView(b);b.setOnClickListener(v->addRepair());call("dashboard",j->{JSONArray a=j.optJSONArray("repairs");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card(x.optString("title"),money(x.optDouble("amount")));}});}
    void addRepair(){EditText t=input("عنوان تعمیر"),a=input("مبلغ به تومان"),d=input("توضیحات");content.addView(t);content.addView(a);content.addView(d);Button b=btn("ثبت تعمیر");content.addView(b);b.setOnClickListener(v->callObj(new JSONObject().put("action","add_repair").put("title",t.getText()).put("amount_rial",Long.parseLong(a.getText().toString())*10).put("description",d.getText()),j->{toast("تعمیر ثبت شد");repairs();}));}
    void payments(){base("پرداخت‌ها");managerDrawer();call("dashboard",j->{JSONArray a=j.optJSONArray("payments");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card("پرداخت واحد "+x.optString("unit_id"),money(x.optDouble("amount"))+" - "+x.optString("status"));}});}
    void plans(){base("اشتراک سامانه");managerDrawer();call("list_plans",j->{if(j instanceof JSONArray)return;});}
    void residentHome(){base("داشبورد ساکن");residentDrawer();call("dashboard",j->{JSONObject u=j.optJSONObject("unit");card("واحد من",u==null?"-":u.optString("unit_no"));card("پرداخت‌های ثبت‌شده",String.valueOf(j.optJSONArray("payments")==null?0:j.optJSONArray("payments").length()));card("شارژ و هزینه‌ها","از منوی کشویی مشاهده کنید");});}
    void residentPay(){base("پرداخت بدهی");residentDrawer();EditText a=input("مبلغ پرداخت به تومان"),n=input("توضیحات");content.addView(a);content.addView(n);Button b=btn("ثبت پرداخت");content.addView(b);b.setOnClickListener(v->callObj(new JSONObject().put("action","add_payment").put("amount_rial",Long.parseLong(a.getText().toString())*10).put("note",n.getText()),j->toast("پرداخت برای تأیید مدیر ثبت شد")));}
    void adminHome(){base("داشبورد مدیرکل سامانه");adminDrawer();call("admin_dashboard",j->{card("تعداد ساختمان‌ها",String.valueOf(j.optJSONArray("buildings")==null?0:j.optJSONArray("buildings").length()));card("طرح‌های اشتراک",String.valueOf(j.optJSONArray("plans")==null?0:j.optJSONArray("plans").length()));card("درخواست‌های اشتراک",String.valueOf(j.optJSONArray("requests")==null?0:j.optJSONArray("requests").length()));});}
    void adminBuildings(){base("مدیریت ساختمان‌ها");adminDrawer();call("admin_dashboard",j->{JSONArray a=j.optJSONArray("buildings");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card(x.optString("name"),x.optString("subscription_status"));}});}
    void adminPlans(){base("مدیریت اشتراک‌ها");adminDrawer();call("admin_dashboard",j->{JSONArray a=j.optJSONArray("plans");for(int i=0;i<(a==null?0:a.length());i++){JSONObject x=a.getJSONObject(i);card(x.optString("name"),money(x.optDouble("price_rial"))+" / "+x.optInt("duration_days")+" روز");}});}
    void adminSettings(){base("تنظیمات سامانه");adminDrawer();call("admin_dashboard",j->{JSONObject x=j.optJSONObject("settings");if(x!=null){card("نام برنامه",x.optString("app_name"));card("دوره آزمایشی",x.optString("free_trial_days")+" روز");card("تأیید ایمیل",x.optBoolean("email_verification_enabled")?"فعال":"غیرفعال");}});}
    void call(String action,JsonConsumer ok){new Thread(()->{try{JSONObject req=new JSONObject().put("action",action);String raw=post(req,session);JSONObject j;if(raw.trim().startsWith("[")){j=new JSONObject().put("data",new JSONArray(raw));}else j=new JSONObject(raw);if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{try{ok.accept(j.has("data")?j.getJSONArray("data"):j);}catch(Exception e){toast(e.getMessage());}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
    void callObj(JSONObject req,JsonConsumer ok){new Thread(()->{try{String raw=post(req,session);JSONObject j=new JSONObject(raw);if(j.has("error"))throw new Exception(j.getString("error"));runOnUiThread(()->{try{ok.accept(j);}catch(Exception e){toast(e.getMessage());}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
    interface JsonConsumer{void accept(JSONObject j)throws Exception;}
    String money(double r){return String.format(Locale.US,"%.0f تومان",r/10.0);}
    void toast(String s){Toast.makeText(this,s==null?"خطا":s,Toast.LENGTH_LONG).show();}
    @Override public void onBackPressed(){if(drawer!=null&&drawer.getVisibility()==View.VISIBLE){drawer.setVisibility(View.GONE);return;}if(!pages.isEmpty()){pages.remove(pages.size()-1);if(role.equals("admin"))adminHome();else if(role.equals("resident"))residentHome();else managerHome();return;}super.onBackPressed();}
}
